import React from "react";
import Header from "./components/Header";
import "./App.css";

function App() {
  return (
    <div>
      <Header />
      <section id="about">
        <h2>About Me</h2>
        <p>I am Yvette, a passionate learner in web development and data science. I love creating useful projects to solve real problems.</p>
      </section>
    </div>
  );
}

export default App;
